import type { Tracker } from "@jini-ai/diagnostics/observability";
import {
  type CreateSitePort,
  listSites as listSitesReal,
  persistActiveSite as persistActiveSiteReal,
  switcherBaseForBinding,
  InitDirNotEmptyError,
  ValidationError,
  resolveNewSiteAdminPassword,
  readSiteRunning as readSiteRunningReal,
  runningSiteUrl,
  type SiteBinding,
  type SiteListEntry,
} from "#src/platform/site-dir/index";
import type { HttpClientPort } from "#src/platform/http/index";
import type { DevRestartPort } from "#src/platform/dev-supervisor/index";
import {
  firstNewSiteAgentPluginTokenRefusal,
  parseNewSiteAgentPluginTokens,
  resolveBundledAgentPlugin,
} from "#src/features/agent-plugins/new-site-agent-plugin-tokens";
import { checkAgentPluginAccessToken as checkAgentPluginAccessTokenReal } from "#src/features/agent-plugins/token-sign-in";

/**
 * @file Create a site and switch the active site — the ONE implementation both the admin Sites
 * screen's HTTP routes (`server/inbound/admin-http/routes/system/sites.ts`) and the assistant's
 * `sites_create_site` / `sites_switch_site` tools call (2026-10-05, big-chat-capabilities plan S1).
 * Moved out of that route file so the chat tool and the button can never drift apart.
 *
 * Every function here returns a refusal VALUE (`{ ok: false, code, error }`) rather than an HTTP
 * status: the route maps `code` to a status, the tool turns it into a thrown error the model reads.
 * Authorization is deliberately NOT done here — the route uses `authorizeOrRespond`, the tool uses
 * `requireToolPermission`; both call {@link resolveSiteSwitchBase} first, then authorize, then the
 * action, in the same order (see that function's doc for why the gate comes before authorize).
 *
 * Create delegates to `site-registry.ts`'s `createSite`, itself a thin wrapper over the SAME
 * `initSite` `tovu init` calls — so a site created here and one created by the CLI are identical.
 *
 * Activate persists the choice (`active-site.ts`'s `persistActiveSite`) and returns explicit restart
 * instructions — it does NOT kill, signal, or re-exec any process (standing rule: no admin API
 * terminates the server on a click). The `restartRequired`/`restartInstructions` fields exist so the
 * UI never has to hardcode that prose itself. Since OD-S1 (2026-10-05) it may instead ASK the
 * `npm run dev` supervisor to restart the API child (`platform/dev-supervisor/dev-restart.ts`) —
 * the supervisor does the restart; this process still never ends itself.
 *
 * Create also takes an optional `agentPluginTokens: { [pluginId]: token }` (2026-09-29): each is
 * checked against the plugin's probe URL first (a rejected one refuses the create, nothing made),
 * then sealed with the NEW site's key into its folder and applied on that site's first boot
 * (`composition/pending-agent-plugin-tokens.ts`). Leaving it out creates the site exactly as before.
 */

/** The exact prose the UI should render after a successful Activate — one source of truth so a
 *  future wording change lands in one place, not wherever a caller happened to hardcode it. */
export const SITE_SWITCH_RESTART_INSTRUCTIONS =
  "Restart the dev server for this to take effect: stop `npm run dev` (Ctrl-C, or SIGTERM the " +
  "dev.mjs process — never a child PID) and start it again.";

export type SiteAdminRefusalCode =
  | "SITE_SWITCHING_DISABLED"
  | "SITE_BINDING_NOT_SWITCHABLE"
  | "VALIDATION_ERROR"
  | "SITE_ALREADY_EXISTS"
  | "SITE_NOT_FOUND"
  | "SITE_ALREADY_RUNNING"
  | "AGENT_PLUGIN_TOKEN_INVALID"
  | "AGENT_PLUGIN_TOKEN_REFUSED"
  | "AGENT_PLUGIN_TOKEN_UNSUPPORTED";

export interface SiteAdminRefusal {
  ok: false;
  code: SiteAdminRefusalCode;
  error: string;
  /** Set only on an `AGENT_PLUGIN_TOKEN_*` refusal: which plugin's token was refused. */
  pluginId?: string;
  /** Existing owner's admin URL, when its listener is ready. Never includes the lease token. */
  url?: string;
}

/** The refusal for a deployment with the site-switcher flag OFF (desktop, hosted). */
const SWITCHING_DISABLED: SiteAdminRefusal = {
  ok: false,
  code: "SITE_SWITCHING_DISABLED",
  error: "site switching is disabled on this deployment",
};

/**
 * The refusal for a boot whose `siteBinding.switcherCompatible` is `false` (2026-09-06,
 * composition-root fix) — an install-dir boot (`tovu serve <dir>`) has no `{cwd, env}`-relative
 * `sites/` tree to Create into or Activate against; `process.cwd()` could be any directory an
 * operator happened to be standing in. The route answers 409, not 403: this is a per-boot structural
 * fact about which `sites/` root exists, not a permissions or deployment-flag refusal.
 */
const BINDING_NOT_SWITCHABLE: SiteAdminRefusal = {
  ok: false,
  code: "SITE_BINDING_NOT_SWITCHABLE",
  error:
    "this server was started against a specific site directory (tovu serve <dir>) with no related sites/ folder to manage — Create/Activate are unavailable",
};

/**
 * The two deployment-wide gates Create and Activate share, in order: the capability flag, then the
 * boot binding. Callers run this BEFORE authorizing — both are per-deployment/per-boot facts
 * independent of the caller's own permissions, so there is no reason to spend an authorize() call
 * on an operation that will be refused either way.
 *
 * Returns the served tree's own base — `null` from `switcherBaseForBinding` exactly when
 * `siteBinding.switcherCompatible` is false — which every write below is rooted at instead of
 * `process.cwd()`, which once created and activated in whatever tree the process was standing in.
 * @complexity O(1); cyclomatic 3.
 */
export function resolveSiteSwitchBase(required: {
  binding: SiteBinding;
  switchingEnabled: boolean;
}): { ok: true; switcherBase: string } | SiteAdminRefusal {
  if (!required.switchingEnabled) return SWITCHING_DISABLED;
  const switcherBase = switcherBaseForBinding(required.binding);
  return switcherBase === null ? BINDING_NOT_SWITCHABLE : { ok: true, switcherBase };
}

export interface CreateSiteForOwnerRequired {
  actorId?: string;
  source?: "admin" | "assistant" | "service";
  adminPassword?: unknown;
  workspaceId: string;
  /** From {@link resolveSiteSwitchBase}: the new site lands at `<switcherBase>/sites/<name>`. */
  switcherBase: string;
  name: string;
  /** Raw, unparsed `{ [pluginId]: token }` — parsed here with the parser `tovu init` shares. */
  agentPluginTokens?: unknown;
}

export interface CreateSiteForOwnerPorts {
  bundledSourceRoot: string;
  credentials?: Pick<import("../agent-plugins/service-ports.js").PluginCredentialsPort, "probe">;
  tracker?: Tracker;
  createSite: CreateSitePort;
  /** The guarded outbound client a token check probes through. Absent, a given token is refused as
   *  not checkable rather than saved unchecked. */
  customCredentialsHttpClient?: HttpClientPort;
  checkAgentPluginAccessToken?: typeof checkAgentPluginAccessTokenReal;
  /** Seals checked tokens into the new site. Lives under `server/` (it needs the site key), so it is
   *  supplied by the caller. Absent, any token is refused before anything is created. */
  sealPendingAgentPluginTokens?: (required: { siteDir: string; siteKeyId: string; tokens: Readonly<Record<string, string>> }) => Promise<void>;
}

export interface CreateSiteForOwnerResult {
  ok: true;
  site: { name: string; dir: string; siteId: string };
  agentPluginTokens: { status: "none" | "saved" | "failed"; pluginIds: string[] };
}

/** The refusal for a token that failed its check, or `null` when every token may be stored. No
 *  guarded HTTP client in these ports means no check can run: every token is then `unsupported`. */
async function checkTokensBeforeCreate(
  workspaceId: string,
  ports: CreateSiteForOwnerPorts,
  tokens: Readonly<Record<string, string>>,
): Promise<SiteAdminRefusal | null> {
  const check = ports.checkAgentPluginAccessToken ?? checkAgentPluginAccessTokenReal;
  const httpClient = ports.customCredentialsHttpClient;
  const resolveInstalledPlugin = resolveBundledAgentPlugin({ bundledSourceRoot: ports.bundledSourceRoot });
  const refusal = await firstNewSiteAgentPluginTokenRefusal(
    // Checked against the bundled plugin the NEW site's first boot seeds, not this site's install.
    async (input) => (httpClient && ports.credentials ? check({ workspaceId, credentials: ports.credentials, resolveInstalledPlugin }, input) : "unsupported"),
    tokens,
  );
  return refusal ? { ok: false, ...refusal, code: refusal.code as SiteAdminRefusalCode } : null;
}

/** Seals the checked tokens into the new site. The site already exists, so a failure here is
 *  reported, not thrown: the person connects from chat instead. */
async function storeTokensForNewSite(
  ports: CreateSiteForOwnerPorts,
  site: { dir: string; siteId: string },
  tokens: Readonly<Record<string, string>>,
): Promise<CreateSiteForOwnerResult["agentPluginTokens"]> {
  const pluginIds = Object.keys(tokens);
  if (pluginIds.length === 0 || !ports.sealPendingAgentPluginTokens) return { status: "none", pluginIds };
  try {
    await ports.sealPendingAgentPluginTokens({ siteDir: site.dir, siteKeyId: site.siteId, tokens });
    return { status: "saved", pluginIds };
  } catch (err) {
    console.error(`[system/sites] the new site's access tokens could not be stored: ${err instanceof Error ? err.message : String(err)}`);
    return { status: "failed", pluginIds };
  }
}

/** Classifies a thrown `createSite()` error into a refusal, or `null` for anything unclassified
 *  that the caller should treat as an internal error. Keeps the mapping in one place so a future
 *  site-registry error type has exactly one spot to be taught about. @complexity O(1); cyclomatic 3. */
function classifyCreateSiteError(err: unknown): SiteAdminRefusal | null {
  if (err instanceof ValidationError) return { ok: false, code: "VALIDATION_ERROR", error: err.message };
  if (err instanceof InitDirNotEmptyError) return { ok: false, code: "SITE_ALREADY_EXISTS", error: err.message };
  return null;
}

/**
 * Creates `<switcherBase>/sites/<name>` (a full `initSite`), optionally checking and sealing access
 * tokens for its bundled Agent Plugins first.
 * @returns the new site, or a refusal (bad name, name taken, a token that failed its check).
 * @throws anything `createSite` throws that is not a known refusal — the caller's 500.
 * @complexity Bounded by `initSite` plus one outbound check per token; cyclomatic 7.
 */
export async function createSiteForOwner(
  required: CreateSiteForOwnerRequired,
  ports: CreateSiteForOwnerPorts,
): Promise<CreateSiteForOwnerResult | SiteAdminRefusal> {
  try {
    const adminPassword = resolveNewSiteAdminPassword(required);
    const parsedTokens = parseNewSiteAgentPluginTokens(required.agentPluginTokens);
    if (!parsedTokens.ok) return { ok: false, code: "VALIDATION_ERROR", error: parsedTokens.error };
    if (Object.keys(parsedTokens.tokens).length > 0 && !ports.sealPendingAgentPluginTokens) {
      return { ok: false, code: "VALIDATION_ERROR", error: "access tokens can't be stored from here — create the site without them and connect later from chat" };
    }
    const refusal = await checkTokensBeforeCreate(required.workspaceId, ports, parsedTokens.tokens);
    if (refusal) return refusal;
    const result = await ports.createSite({ name: required.name, adminPassword }, { cwd: required.switcherBase });
    trackCreatedSite({ required, site: result }, ports);
    const agentPluginTokens = await storeTokensForNewSite(ports, result, parsedTokens.tokens);
    return { ok: true, site: { name: result.name, dir: result.dir, siteId: result.siteId }, agentPluginTokens };
  } catch (err) {
    const classified = classifyCreateSiteError(err);
    if (classified) return classified;
    throw err;
  }
}

function trackCreatedSite({ required, site }: { required: CreateSiteForOwnerRequired; site: CreateSiteForOwnerResult["site"] }, ports: Pick<CreateSiteForOwnerPorts, "tracker">): void {
  // initSite has committed; later optional credential setup cannot turn this into another creation.
  try { ports.tracker?.capture({ name: "site_created", userId: required.actorId ?? `system:${required.workspaceId}` }, { properties: {
    targetSiteId: site.siteId, templateKind: "default", source: required.source ?? "service",
  } }); } catch { /* Product analytics cannot fail an already-created site. */ }
}

/** What the person is told when the dev supervisor is restarting the server for them (S2). */
export const SITE_SWITCH_RESTARTING_NOTICE =
  "The dev server is restarting onto the new site now. The admin reconnects by itself in a few seconds — nothing to do.";

export interface ActivateSiteRequired {
  /** Actual boot binding, independent of a pending persisted selection. */
  currentSiteName?: string;
  /** From {@link resolveSiteSwitchBase}. Both the lookup and the `.env` write are rooted here. */
  switcherBase: string;
  name: string;
  /** Ask the dev supervisor to restart now (OD-S1, 2026-10-05). Ignored when there is none. */
  restartNow?: boolean;
  /** `siteBinding.dirOverridden`: `TOVU_SITE_DIR` wins over `TOVU_SITE`, so a restart would come
   *  back on the SAME site — never restart for nothing. */
  dirOverridden?: boolean;
}

export interface ActivateSitePorts {
  listSites?: (optional?: { cwd?: string }) => readonly SiteListEntry[];
  /** Fresh lease read before any write; list snapshots can be stale. */
  readSiteRunning?: typeof readSiteRunningReal;
  workspace?: NonNullable<Parameters<typeof readSiteRunningReal>[1]>["workspace"];
  persistActiveSite?: typeof persistActiveSiteReal;
  /** Present only under `npm run dev` (`platform/dev-supervisor`). `null`/absent = no supervisor. */
  devRestart?: DevRestartPort | null;
}

export interface ActivateSiteResult {
  ok: true;
  activeSiteName: string;
  restartRequired: boolean;
  restartInstructions: string;
  /** Set only when `restartNow` was asked: whether a restart was actually requested. */
  restarting?: boolean;
}

/** Whether to fire the restart, and if not, why (so the person is told the real reason). Only
 *  called once `activateSite` has seen `restartNow`, so no "not asked to restart" case lives here. */
function restartDecision(required: ActivateSiteRequired, devRestart: DevRestartPort | null | undefined): { restart: boolean; note?: string } {
  if (devRestart?.canSwitchSite === false) return { restart: false };
  if (required.dirOverridden) {
    return { restart: false, note: " Not restarting: TOVU_SITE_DIR is set, so a restart would come back on the same site — unset it first." };
  }
  return devRestart ? { restart: true } : { restart: false };
}

/** Observe the boot lease before changing selection; unreadable records propagate fail closed.
 * @returns A plain refusal with the owner's URL, or null for an idle target.
 * @complexity O(1) lease I/O and liveness check.
 */
function runningSiteRefusal({ dir, name }: { dir: string; name: string }, ports: ActivateSitePorts = {}): SiteAdminRefusal | null {
  const running = (ports.readSiteRunning ?? readSiteRunningReal)({ dir }, { workspace: ports.workspace });
  if (!running) return null;
  const url = runningSiteUrl({ record: running });
  const location = url ? `open in ${running.app} at ${url}` : `starting in ${running.app}. Wait for it to finish starting`;
  // Both switch entrypoints must explain how to free the target before .env or the API changes.
  const error = running.app === "Desktop" && url
    ? `That site is open in the Desktop app at ${url} — close it there first or open it there`
    : `Site '${name}' is ${location}. Switch refused; the current site is still running.`;
  return { ok: false, code: "SITE_ALREADY_RUNNING", ...(url ? { url } : {}),
    error };
}

/**
 * Makes `name` the site the NEXT dev-server start serves (`TOVU_SITE=<name>` in the switcher tree's
 * `.env`). Looks the name up with the strict `listSites()` — an `unregistered` served folder is not
 * a valid target, because `tovu serve` would refuse it.
 *
 * With `restartNow` and a dev supervisor (`ports.devRestart`, only under `npm run dev`), it also asks
 * the supervisor to restart the API child onto the new site. Still never kills this process itself.
 * Refuses a live target before writing `.env` or requesting a restart. Boot's atomic claim remains
 * authoritative if another process starts after this check; the supervisor restores the old site.
 * @throws Lease read failures; undecidable ownership must never permit a switch.
 * @complexity O(sites) for the lookup, one lease read, and at most one `.env` rewrite.
 */
export function activateSite(
  required: ActivateSiteRequired,
  ports: ActivateSitePorts = {},
): ActivateSiteResult | SiteAdminRefusal {
  const { switcherBase, name } = required;
  const match = (ports.listSites ?? listSitesReal)({ cwd: switcherBase }).find((site) => site.name === name);
  if (!match) return { ok: false, code: "SITE_NOT_FOUND", error: `site '${name}' was not found` };
  if (name === required.currentSiteName) {
    // Re-selecting the running site cancels a pending switch, so the next start stays here too.
    (ports.persistActiveSite ?? persistActiveSiteReal)({ name }, { cwd: switcherBase });
    return { ok: true, activeSiteName: name, restartRequired: false, restartInstructions: "This site is already active.", restarting: false };
  }
  const refusal = runningSiteRefusal({ dir: match.dir, name }, ports);
  if (refusal) return refusal;
  (ports.persistActiveSite ?? persistActiveSiteReal)({ name }, { cwd: switcherBase });
  return siteActivationRestartResult(required, ports);
}

/** Selection is persisted before any restart decision or supervisor request. */
function siteActivationRestartResult(required: ActivateSiteRequired, ports: Pick<ActivateSitePorts, "devRestart">): ActivateSiteResult {
  const { name } = required;
  const base = { ok: true as const, activeSiteName: name, restartRequired: true as const };
  if (!required.restartNow) return { ...base, restartInstructions: SITE_SWITCH_RESTART_INSTRUCTIONS };
  const decision = restartDecision(required, ports.devRestart);
  if (!decision.restart) return { ...base, restartInstructions: SITE_SWITCH_RESTART_INSTRUCTIONS + (decision.note ?? ""), restarting: false };
  ports.devRestart!.requestRestart({ reason: `switch site to '${name}'` });
  return { ...base, restartInstructions: SITE_SWITCH_RESTARTING_NOTICE, restarting: true };
}

import { isUtf8 } from "node:buffer";
import { randomBytes } from "node:crypto";
import { constants as fsConstants, copyFileSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, realpathSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";

import { rewriteThemeAssetPaths } from "./asset-path-rewrites.js";
import { fileExtension, fileGroup, TRASH_DIR_NAME } from "./file-identity-lock.js";
import { isRecognizedThemeRoot, MAX_LISTED_FILES, MAX_THEME_FILE_BYTES, MAX_WALK_DEPTH } from "./theme-files.js";
import { writeGeneratedThemeOriginal } from "./sync-originals.js";
import { keepStructureFile, prepareStructureTheme } from "./structure-only-theme.js";
import { MIGRATION_STAGING_DIR_PREFIX, nextAvailableThemeId, rescanThemes, THEME_CATALOG_DIR, type DiscoveredTheme, type ThemeTier } from "./theme.js";

/**
 * @file `duplicateTheme` — the one way a NEW theme folder comes into existence at runtime: copy an
 * existing discovered theme (a stock theme the site was seeded with counts — every stock theme is
 * a discovered theme under the site's own `themesDir`) into a fresh sibling folder, then give the
 * copy its own identity in `theme.json`.
 *
 * Two callers, one service (owner, 2026-10-08): the `theme_duplicate` agent tool
 * (`duplicate-theme-tool.ts`) and the admin Themes screen's Duplicate action
 * (`server/inbound/admin-http/routes/themes/duplicate.ts`). Both go through
 * {@link duplicateDiscoveredTheme}, so "what id does the copy get", "what counts as taken", and
 * "what gets refused" can never differ between the human and the agent.
 *
 * Same "copy the original, edit the copy" model `development/scripts/theme-tool.ts`'s `copy`
 * command implements for the CLI, including its `lineage` manifest field and its id-assignment rule
 * ({@link nextAvailableThemeId}). The source is only ever READ: every write lands in a staging
 * folder that is renamed into place at the end, so a refusal or crash halfway never leaves a
 * half-copied theme for discovery to find, and never touches the source.
 *
 * Generic? No — this is Tovu's on-disk theme layout (`<themesRoot>/<tier>/<id>/theme.json`), not a
 * Jini concern.
 */

/** Total bytes one duplicate may copy. 50 × the per-file text ceiling: the largest stock theme is
 *  ~2.5MB, so this only stops a pathological folder, never a real theme. */
export const MAX_DUPLICATE_THEME_BYTES = MAX_THEME_FILE_BYTES * 50;

/** Display-name length ceiling — a label, not a description. */
const MAX_THEME_NAME_LENGTH = 120;

/** Folder-safe id: lowercase alphanumerics and single hyphens, no leading/trailing hyphen, ≤ 64
 *  chars. Excludes `.`/`_` outright, so an id can never spell `..`, a dot-folder, or a `__catalog__`
 *  name. */
const THEME_ID_PATTERN = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

/** The version a copy starts at — it is a new theme, not the source's next release. */
const DUPLICATE_INITIAL_VERSION = "1.0.0";

export type DuplicateThemeErrorCode =
  | "SOURCE_NOT_FOUND"
  | "INVALID_NAME"
  | "INVALID_ID"
  | "ID_TAKEN"
  | "SOURCE_NOT_COPYABLE"
  | "SYMLINK"
  | "TOO_LARGE"
  | "BAD_MANIFEST";

/** Every refusal {@link duplicateTheme} raises. A different input (or a different source) fixes each
 *  one, so callers map it to a 4xx / a tool input error, never a 500. `ID_TAKEN` is a conflict. */
export class DuplicateThemeError extends Error {
  readonly code: DuplicateThemeErrorCode;
  constructor(code: DuplicateThemeErrorCode, message: string) {
    super(message);
    this.name = "DuplicateThemeError";
    this.code = code;
  }
}

export interface DuplicateThemeResult {
  id: string;
  name: string;
  tier: ThemeTier;
  /** Absolute folder of the new theme. Callers addressing a model or a browser drop this. */
  dir: string;
  sourceThemeId: string;
  files: number;
  bytes: number;
  /** Present only for a structure copy; valid loading does not establish styling readiness. */
  stylingStatus?: "unstyled";
}

/** Omitted mode preserves the full-copy API used by the admin Duplicate action. */
export interface DuplicateThemeOptions {
  newId?: string;
  stagingSuffix?: () => string;
  mode?: "full" | "structure-only";
}

/** Refuse unsupported presentation stripping before creating staging or originals. */
function validateStructureSource(source: DiscoveredTheme, mode: DuplicateThemeOptions["mode"]): void {
  if (mode !== "structure-only") return;
  if (source.manifest.apiVersion === 2 && source.manifest.tier === "static" && source.manifest.build?.source !== "compiled") return;
  throw new DuplicateThemeError("SOURCE_NOT_COPYABLE", "Structure-only duplication needs an authored v2 static theme. Choose Tovu Starter, or use mode 'full' for an exact copy.");
}

/**
 * Turn a display name into a folder-safe id candidate: strip diacritics, lowercase, collapse every
 * run of non-alphanumerics to one hyphen, trim hyphens, cap at 48 chars (leaving room for a `-N`
 * suffix inside {@link THEME_ID_PATTERN}'s 64). Empty when the name has no Latin letters/digits.
 * @complexity O(n) in the name length.
 */
export function themeIdFromName(name: string): string {
  return name
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 48)
    .replace(/-$/, "");
}

/** Trimmed, length-checked, control-character-free display name, or a refusal. */
function validateThemeName(newName: string): string {
  const name = newName.trim();
  if (name.length === 0) throw new DuplicateThemeError("INVALID_NAME", "newName must not be empty");
  if (name.length > MAX_THEME_NAME_LENGTH) {
    throw new DuplicateThemeError("INVALID_NAME", `newName must be at most ${MAX_THEME_NAME_LENGTH} characters`);
  }
  // eslint-disable-next-line no-control-regex
  if (/[\u0000-\u001f\u007f]/.test(name)) throw new DuplicateThemeError("INVALID_NAME", "newName must not contain control characters");
  return name;
}

/**
 * The id the copy gets. An explicit `newId` is the caller's exact choice: malformed or taken is
 * refused, never silently suffixed (the caller asked for THAT id). An omitted one is derived from the
 * name and suffixed `-1`, `-2`, … through {@link nextAvailableThemeId} — the CLI's rule.
 */
function assignThemeId(
  required: { source: DiscoveredTheme; themesRoot: string; name: string; takenIds: ReadonlySet<string> },
  optional: { newId?: string }
): string {
  const { source, themesRoot, name, takenIds } = required;
  const parentDir = dirname(source.dir);
  const alsoTaken = (id: string): boolean => takenIds.has(id) || existsSync(join(parentDir, id));
  const pick = (desiredId: string): string =>
    nextAvailableThemeId({ desiredId, themesRoot, tier: source.manifest.tier }, { alsoTaken });

  if (optional.newId !== undefined) {
    if (!THEME_ID_PATTERN.test(optional.newId)) {
      throw new DuplicateThemeError(
        "INVALID_ID",
        `newId '${optional.newId}' must be lowercase letters, digits and single hyphens (1-64 chars, no leading/trailing hyphen)`
      );
    }
    if (pick(optional.newId) !== optional.newId) {
      throw new DuplicateThemeError("ID_TAKEN", `theme id '${optional.newId}' is already taken — pick another newId, or omit it to get a free one`);
    }
    return optional.newId;
  }
  return pick(themeIdFromName(name) || `${source.manifest.id}-copy`);
}

/** One file to copy, relative to the theme folder (`/`-separated). */
interface PlannedFile {
  relativePath: string;
  bytes: number;
}

/** What {@link planThemeCopy} accumulates: every file and folder to create, and the total bytes. */
interface ThemeCopyPlan {
  files: PlannedFile[];
  dirs: string[];
  bytes: number;
}

/**
 * Walk the source folder and plan the copy, refusing — before a single byte is written — anything
 * the theme store would not hold: a symlink anywhere (never followed, never copied: a link is how a
 * copy would read outside the theme), more files than {@link MAX_LISTED_FILES}, deeper than
 * {@link MAX_WALK_DEPTH}, or more than {@link MAX_DUPLICATE_THEME_BYTES} in total. The top-level
 * `.trash/` is skipped: soft-deleted files are not part of the theme.
 * @complexity O(n) in the source's file count, one `lstat` each.
 */
function planThemeCopy(sourceDir: string): ThemeCopyPlan {
  const plan: ThemeCopyPlan = { files: [], dirs: [], bytes: 0 };
  planThemeFolder({ plan, absDir: sourceDir, relDir: "", depth: 0 });
  return plan;
}

/**
 * Plan one folder of the copy (depth-first, sorted), recursing through {@link planThemeEntry}.
 * @throws {DuplicateThemeError} `TOO_LARGE` past {@link MAX_WALK_DEPTH}, plus every entry refusal.
 * @complexity O(e) in the folder's entry count, plus the recursion.
 */
function planThemeFolder(required: { plan: ThemeCopyPlan; absDir: string; relDir: string; depth: number }): void {
  const { absDir, relDir, depth } = required;
  if (depth > MAX_WALK_DEPTH) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme is nested deeper than ${MAX_WALK_DEPTH} folders ('${relDir}')`);
  }
  for (const entry of readdirSync(absDir).sort()) {
    const relativePath = relDir ? `${relDir}/${entry}` : entry;
    if (relativePath === TRASH_DIR_NAME) continue;
    planThemeEntry({ plan: required.plan, absPath: join(absDir, entry), relativePath, depth });
  }
}

/**
 * Plan one folder entry: refuse a symlink, recurse into a folder, record a regular file, and skip
 * anything else (FIFOs, sockets, devices are not theme content).
 * @throws {DuplicateThemeError} `SYMLINK`, or a {@link planThemeFolder} / {@link addPlannedFile} refusal.
 * @complexity O(1) plus the recursion for a folder.
 */
function planThemeEntry(required: { plan: ThemeCopyPlan; absPath: string; relativePath: string; depth: number }): void {
  const { plan, absPath, relativePath, depth } = required;
  const stat = lstatSync(absPath);
  if (stat.isSymbolicLink()) {
    throw new DuplicateThemeError("SYMLINK", `source theme contains a symbolic link ('${relativePath}'); themes with links cannot be duplicated`);
  }
  if (stat.isDirectory()) {
    plan.dirs.push(relativePath);
    planThemeFolder({ plan, absDir: absPath, relDir: relativePath, depth: depth + 1 });
    return;
  }
  if (stat.isFile()) addPlannedFile({ plan, file: { relativePath, bytes: stat.size } });
}

/**
 * Record one file in the plan, refusing once the plan passes {@link MAX_LISTED_FILES} files or
 * {@link MAX_DUPLICATE_THEME_BYTES} bytes.
 * @throws {DuplicateThemeError} `TOO_LARGE`.
 * @complexity O(1).
 */
function addPlannedFile(required: { plan: ThemeCopyPlan; file: PlannedFile }): void {
  const { plan, file } = required;
  plan.bytes += file.bytes;
  plan.files.push(file);
  if (plan.files.length > MAX_LISTED_FILES) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme has more than ${MAX_LISTED_FILES} files`);
  }
  if (plan.bytes > MAX_DUPLICATE_THEME_BYTES) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme is larger than ${MAX_DUPLICATE_THEME_BYTES} bytes`);
  }
}

/**
 * Give the staged copy its own identity: `id` (must equal the folder name or the theme loads
 * `invalid`), `name`, a reset `version`, and `lineage` — the same metadata-only record the CLI's
 * `copy` writes (nothing at runtime reads it; it answers "what was this forked from").
 */
function rewriteCopiedManifest(stagingDir: string, identity: { id: string; name: string; source: DiscoveredTheme; mode?: DuplicateThemeOptions["mode"] }): void {
  const manifestPath = join(stagingDir, "theme.json");
  let manifest: unknown;
  try {
    manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  } catch {
    throw new DuplicateThemeError("BAD_MANIFEST", `source theme '${identity.source.manifest.id}' has no readable theme.json`);
  }
  if (typeof manifest !== "object" || manifest === null || Array.isArray(manifest)) {
    throw new DuplicateThemeError("BAD_MANIFEST", `source theme '${identity.source.manifest.id}' has a theme.json that is not a JSON object`);
  }
  const record = manifest as Record<string, unknown>;
  const sourceVersion = String(record.version ?? identity.source.manifest.version);
  record.id = identity.id;
  record.name = identity.name;
  record.version = DUPLICATE_INITIAL_VERSION;
  record.lineage = { from: identity.source.manifest.id, tier: identity.source.manifest.tier, version: sourceVersion };
  if (identity.mode === "structure-only") record.fontStylesheets = [];
  writeFileSync(manifestPath, `${JSON.stringify(record, null, 2)}\n`, "utf8");
}

/** Copy the bounded plan to staging, rebind asset paths, then strip presentation for structure drafts. The outer
 * service owns cleanup on failure; all transformations precede the originals snapshot. */
function copyStagedTheme(required: { sourceDir: string; stagingDir: string; plan: ThemeCopyPlan; sourceThemeId: string; id: string; mode?: DuplicateThemeOptions["mode"] }): void {
  const { sourceDir, stagingDir, plan, sourceThemeId, id, mode } = required;
  mkdirSync(stagingDir);
  for (const dir of plan.dirs) mkdirSync(join(stagingDir, dir), { recursive: true });
  for (const file of plan.files) {
    copyFileSync(join(sourceDir, file.relativePath), join(stagingDir, file.relativePath), fsConstants.COPYFILE_EXCL);
  }
  // Stripping must see the rebound id so retained absolute vendor stylesheet links still match.
  rewriteCopiedAssetPaths({ stagingDir, files: plan.files, sourceThemeId, targetThemeId: id });
  if (mode !== "structure-only") return;
  prepareStructureTheme({ stagingDir, files: plan.files, themeId: id });
  const css = { relativePath: "css/theme.css", bytes: lstatSync(join(stagingDir, "css/theme.css")).size };
  addPlannedFile({ plan, file: css });
}

/**
 * Rebind absolute asset URLs in every staged text file before the copy and its stored original
 * become visible. Reuse the theme file groups to skip binary media (SVG is text), then inspect
 * bytes so templates, CSS and manifests all participate, including extensionless text. NUL-bearing
 * or invalid UTF-8 files stay byte-identical: decoding binary assets as UTF-8 and writing them back
 * would corrupt them.
 *
 * @throws Whatever `node:fs` throws; the caller removes staging on failure.
 * @complexity O(b) time and O(m) space for total copied bytes b and largest file size m, bounded by
 * the already-checked copy plan.
 */
function rewriteCopiedAssetPaths(required: {
  stagingDir: string;
  files: readonly PlannedFile[];
  sourceThemeId: string;
  targetThemeId: string;
}): void {
  const { stagingDir, files, sourceThemeId, targetThemeId } = required;
  for (const file of files) {
    if (fileGroup(file.relativePath, undefined) === "asset" && fileExtension(file.relativePath) !== ".svg") continue;
    const filePath = join(stagingDir, file.relativePath);
    const bytes = readFileSync(filePath);
    if (!bytes.includes(0) && isUtf8(bytes)) {
      const original = bytes.toString("utf8");
      const rewritten = rewriteThemeAssetPaths(
        { content: original, sourceThemeId, rules: [{ v1Prefix: "", v2Prefix: "" }] },
        { targetThemeId }
      );
      if (rewritten !== original) writeFileSync(filePath, rewritten, "utf8");
    }
  }
}

/**
 * Snapshot the just-created copy into the site's originals catalog
 * (`<themesRoot>/__original-themes__/<tier>/<id>`), the same place a seeded theme's original lives,
 * so the copy's Explore has something to Reset to and shows no "no stored original" banner (owner
 * 2026-10-08). Reuses `writeGeneratedThemeOriginal` — the generator the shipped originals come from —
 * so a copy's original is filtered exactly like theirs. `nextAvailableThemeId` already counts a
 * catalog folder as taken, so the target is free and nothing existing is replaced.
 *
 * A copy without its original is the state this exists to end, so a failure here removes the copy
 * (a folder this same call just created) and rethrows — the caller sees one failed duplicate.
 *
 * @throws Whatever `node:fs` throws writing the catalog folder, after removing `destDir`.
 * @complexity O(f) in the copy's file count.
 */
function writeCopyOriginal(required: { destDir: string; themesRoot: string; tier: ThemeTier; id: string }): void {
  const { destDir, themesRoot, tier, id } = required;
  try {
    writeGeneratedThemeOriginal({ liveDir: destDir, targetDir: join(themesRoot, THEME_CATALOG_DIR, tier, id) });
  } catch (err) {
    rmSync(destDir, { recursive: true, force: true });
    throw err;
  }
}

/**
 * Copy `source` into a new sibling theme folder named after the assigned id.
 *
 * @param required.source - The discovered theme to copy. Only read, never written.
 * @param required.themesRoot - The site's themes root (`RouteDeps.themesDir`); the source must sit at
 * a recognized theme root under it.
 * @param required.newName - Display name for the copy (`theme.json` `name`).
 * @param required.takenIds - Every discovered theme id; the copy's id must not collide with any.
 * @param optional.newId - Exact id to use; refused if malformed or taken. Omitted ⇒ derived from
 * `newName` and suffixed until free.
 * @param optional.stagingSuffix - Test seam for the staging folder's random suffix.
 * @param optional.mode - `structure-only` strips authored-v2 presentation and marks the copy unstyled.
 * @returns The new theme's id, name, tier, folder, and what was copied.
 * @throws {DuplicateThemeError} On any refusal; nothing is left on disk. A failed write of the copy's
 * stored original ({@link writeCopyOriginal}) also leaves nothing — the copy is removed.
 * @complexity O(n + b) in the source's file count and bytes (copied twice: the theme and its original).
 */
export function duplicateTheme(
  required: { source: DiscoveredTheme; themesRoot: string; newName: string; takenIds: ReadonlySet<string> },
  optional: DuplicateThemeOptions = {}
): DuplicateThemeResult {
  const { source, themesRoot, takenIds } = required;
  validateStructureSource(source, optional.mode);
  if (!isRecognizedThemeRoot({ themeDir: source.dir, themesRoot }) || !existsSync(source.dir)) {
    throw new DuplicateThemeError("SOURCE_NOT_COPYABLE", `theme '${source.manifest.id}' is not inside this site's themes folder`);
  }
  const name = validateThemeName(required.newName);
  const id = assignThemeId({ source, themesRoot, name, takenIds }, { newId: optional.newId });

  const sourceDir = realpathSync(source.dir);
  const plan = planThemeCopy(sourceDir);
  if (optional.mode === "structure-only") {
    plan.files = plan.files.filter(file => keepStructureFile(file));
    plan.bytes = plan.files.reduce((bytes, file) => bytes + file.bytes, 0);
  }
  const parentDir = dirname(source.dir);
  const destDir = join(parentDir, id);
  const suffix = optional.stagingSuffix?.() ?? randomBytes(6).toString("hex");
  const stagingDir = join(parentDir, `${MIGRATION_STAGING_DIR_PREFIX}duplicate-${id}-${suffix}`);

  try {
    copyStagedTheme({ sourceDir, stagingDir, plan, sourceThemeId: source.manifest.id, id, mode: optional.mode });
    rewriteCopiedManifest(stagingDir, { id, name, source, mode: optional.mode });
    // Re-checked right before the rename: `renameSync` onto an EMPTY existing directory replaces it
    // silently on POSIX, so a folder created since `assignThemeId` must be refused here, not merged.
    if (existsSync(destDir)) throw new DuplicateThemeError("ID_TAKEN", `theme id '${id}' was taken while copying — try again`);
    renameSync(stagingDir, destDir);
  } catch (err) {
    rmSync(stagingDir, { recursive: true, force: true });
    throw err;
  }
  writeCopyOriginal({ destDir, themesRoot, tier: source.manifest.tier, id });

  return { id, name, tier: source.manifest.tier, dir: destDir, sourceThemeId: source.manifest.id, files: plan.files.length, bytes: plan.bytes,
    ...(optional.mode === "structure-only" ? { stylingStatus: "unstyled" as const } : {}) };
}

/**
 * The service both callers use: find `sourceThemeId` among the live discovered themes, duplicate it,
 * then {@link rescanThemes} so the copy is in `themes` (the array every request reads) before this
 * returns — a duplicate the next page view cannot see would look like a failure.
 *
 * @returns The duplicate's result plus the copy's discovered entry (its `status`/`errors` tell the
 * caller whether it loaded `valid`).
 * @throws {DuplicateThemeError} `SOURCE_NOT_FOUND` for an unknown id, plus every {@link duplicateTheme} refusal.
 * @complexity O(n + b) for the copy, plus one full rediscovery (O(t) themes).
 */
export function duplicateDiscoveredTheme(
  required: { themes: DiscoveredTheme[]; themesDir: string; sourceThemeId: string; newName: string },
  optional: DuplicateThemeOptions = {}
): { result: DuplicateThemeResult; theme: DiscoveredTheme | undefined } {
  const { themes, themesDir, sourceThemeId, newName } = required;
  const source = themes.find((t) => t.manifest.id === sourceThemeId);
  if (!source) {
    const known = themes.map((t) => t.manifest.id).join(", ") || "(none discovered)";
    throw new DuplicateThemeError("SOURCE_NOT_FOUND", `theme '${sourceThemeId}' was not found — discovered themes are: ${known}`);
  }
  const takenIds = new Set(themes.map((t) => t.manifest.id));
  const result = duplicateTheme({ source, themesRoot: themesDir, newName, takenIds }, optional);
  rescanThemes({ themes, dir: themesDir });
  return { result, theme: themes.find((t) => t.manifest.id === result.id && basename(t.dir) === result.id) };
}

import { Liquid, Hash, type TagToken } from "liquidjs";

/**
 * @file ADR-020 Tier-2 guardrail: the allowlist of LiquidJS tags/filters a
 * "templated" theme may use, plus the AST-walking check that enforces it.
 *
 * Purpose:
 * A Tier-2 theme ships raw `.liquid` source that runs on our server (ADR-020
 * §3, drift finding C6). This module keeps that surface to pure, non-I/O
 * logic: no `{% include %}` / `{% render %}` / `{% layout %}` / `{% block %}`
 * (LiquidJS's own filesystem-reading tags — distinct from Tovu's custom
 * `render_block`, which resolves against the trusted in-process component
 * registry, not the filesystem) and no filter beyond a reviewed, I/O-free
 * set. Enforcement walks the *parsed AST* (`liquid.parse()`), not the raw
 * source text, so a tag/filter name appearing inside a string literal or
 * comment can't trigger a false positive/negative.
 *
 * How it relates to the project:
 * Called from two sites, matching ADR-020 §3's "lint before publish" +
 * "defensive at render time" pair:
 *   - `features/theme/theme.ts`'s `loadTheme()` — lint every `.liquid` file
 *     at discovery time, folding violations into the existing
 *     `errors`/`status: "invalid"` mechanism.
 *   - `server/http/site/liquid-worker.ts` — a second, redundant check
 *     immediately before render, in case a template was hot-edited on disk
 *     after a theme was validated (belt-and-suspenders; loadTheme's result
 *     is not re-verified per request).
 */

/**
 * Built-in LiquidJS tags this repo's themes may use. Everything else in
 * LiquidJS's default tag registry — `include`, `render`, `layout`, `block`
 * — reads named partial/layout files from the engine's configured `fs`/
 * `root` and is excluded on principle: Tier 2 has zero filesystem access
 * (see `liquid-worker.ts`'s explicit no-op `fs` adapter for the second,
 * redundant layer of that guarantee, verified empirically — LiquidJS's
 * *default* engine config is not filesystem-inert, it reads real files
 * relative to `root: ["."]` unless an `fs` adapter is supplied). `liquid`
 * (the multi-statement shorthand tag) is allowed because its body parses
 * through this same walker — nested tags inside it are enumerated exactly
 * like top-level ones, verified by the smuggling-attempt test in
 * `liquid-allowlist.test.ts`. `render_block` is Tovu's own tag.
 */
export const ALLOWED_LIQUID_TAGS: ReadonlySet<string> = new Set([
  "render_block",
  "comment",
  "if",
  "unless",
  "case",
  "for",
  "assign",
  "capture",
  "break",
  "continue",
  "cycle",
  "increment",
  "decrement",
  "echo",
  "raw",
  "tablerow",
  "liquid",
]);

/**
 * Built-in LiquidJS filters this repo's themes may use: string/array/number
 * shaping only. LiquidJS ships no filesystem, network, or shell-invoking
 * filter by default (checked against the engine's full built-in filter
 * registry). The crypto/encoding filters (`sha256`, `hmac_sha256`,
 * `base64_encode`/`base64_decode`) and the `_exp` filters (which evaluate an
 * attacker-supplied expression string as a small boolean-expression
 * language, e.g. `where_exp`) are excluded on the same least-privilege
 * basis as the tag list: no shipped theme needs them, they are not "common
 * string/array" filters, and the `_exp` family in particular re-opens a
 * dynamic-evaluation surface this allowlist exists to close.
 */
export const ALLOWED_LIQUID_FILTERS: ReadonlySet<string> = new Set([
  "abs",
  "append",
  "array_to_sentence_string",
  "at_least",
  "at_most",
  "capitalize",
  "ceil",
  "compact",
  "concat",
  "date",
  "default",
  "divided_by",
  "downcase",
  "escape",
  "escape_once",
  "find",
  "find_index",
  "first",
  "floor",
  "group_by",
  "has",
  "join",
  "json",
  "jsonify",
  "last",
  "lstrip",
  "map",
  "minus",
  "modulo",
  "newline_to_br",
  "normalize_whitespace",
  "number_of_words",
  "plus",
  "prepend",
  "raw",
  "reject",
  "remove",
  "remove_first",
  "remove_last",
  "replace",
  "replace_first",
  "replace_last",
  "reverse",
  "round",
  "rstrip",
  "size",
  "slice",
  "slugify",
  "sort",
  "sort_natural",
  "split",
  "strip",
  "strip_html",
  "strip_newlines",
  "sum",
  "times",
  "to_integer",
  "truncate",
  "truncatewords",
  "uniq",
  "upcase",
  "uri_escape",
  "url_decode",
  "url_encode",
  "where",
  "xml_escape",
]);

/**
 * A parse-only Liquid engine used solely to build an AST to walk — it is
 * never rendered, so it needs no `fs` hardening of its own (parsing never
 * touches disk; verified in `liquid-allowlist.test.ts` against a bare
 * default-`fs` engine instance). `render_block` is registered as an inert
 * stub purely so parsing a legitimate template doesn't fail with LiquidJS's
 * own "tag not found" parse error on Tovu's custom tag.
 */
const parser = new Liquid({ cache: false });
parser.registerTag("render_block", {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  parse(this: any, token: TagToken) {
    this.hash = new Hash(token.args);
  },
  render(): string {
    return "";
  },
});

/**
 * `{% for i in (1..N) %}` — a numeric range literal — is a reachable
 * resource-exhaustion vector *even though `for` is an allowlisted tag*: a
 * template needs no disallowed tag or filter to write `(1..99999999999)`.
 * Verified empirically that LiquidJS eagerly materializes the *whole* range
 * into a real JS array before iterating (not a lazy generator), and that a
 * single allocation this large can hit V8's fatal (process-crashing) OOM
 * path even inside a `resourceLimits`-capped `worker_threads` worker —
 * `resourceLimits` protects against *gradual* heap growth (proven in
 * `liquid-sandbox.test.ts`'s memory-blowup test) but not a one-shot
 * allocation request that already exceeds the isolate's budget before any
 * GC/limit callback gets a chance to intervene. Capping the literal span at
 * lint time closes the one instance of this class reachable through purely
 * allowlisted syntax; no shipped theme needs a bare numeric range this
 * large (`themes/dispatch` loops over real arrays, e.g. `for post in
 * posts`, never a synthetic range).
 */
const MAX_FOR_RANGE_SPAN = 1_000_000;

/**
 * The minimal shape this walker relies on across every LiquidJS AST node
 * kind (`Tag` subclasses, `Output`, `HTML`). All fields are optional because
 * different node kinds populate different subsets — `HTML` nodes have none
 * of them; `Output` has `value` and `arguments`; `Tag` subclasses have
 * `name` and, for branching/looping tags, `children`; `ForTag` additionally
 * has `collection`, which is a `RangeToken` (with numeric `lhs`/`rhs`) only
 * when the loop source is a literal range rather than a variable/array.
 */
interface WalkableNode {
  name?: string;
  value?: { filters?: Array<{ name: string }> };
  arguments?: () => Iterable<{ filters?: Array<{ name: string }> } | undefined>;
  children?: (partials: boolean, sync: boolean) => Generator<unknown, WalkableNode[]>;
  collection?: { lhs?: { content?: unknown }; rhs?: { content?: unknown } };
}

/** Records `node`'s own tag name, if it has one. */
function collectNodeTag(node: WalkableNode, tags: Set<string>): void {
  if (typeof node.name === "string") tags.add(node.name);
}

/** Records the filters applied directly to `node.value` (an `Output` node's own `{{ x | filter }}` chain). */
function collectNodeValueFilters(node: WalkableNode, filters: Set<string>): void {
  for (const filter of node.value?.filters ?? []) filters.add(filter.name);
}

/** Records filters used inside `node`'s own tag arguments (e.g. an `assign`/`if` expression's filters). */
function collectNodeArgumentFilters(node: WalkableNode, filters: Set<string>): void {
  if (typeof node.arguments !== "function") return;
  for (const arg of node.arguments()) {
    for (const filter of arg?.filters ?? []) filters.add(filter.name);
  }
}

/** Flags an oversized literal `for` range into `rangeViolations` — see `MAX_FOR_RANGE_SPAN`'s own doc. */
function collectForRangeViolation(node: WalkableNode, rangeViolations: string[]): void {
  if (node.name !== "for" || !node.collection) return;
  const lhs = node.collection.lhs?.content;
  const rhs = node.collection.rhs?.content;
  if (typeof lhs === "number" && typeof rhs === "number" && Math.abs(rhs - lhs) > MAX_FOR_RANGE_SPAN) {
    rangeViolations.push(`for-loop range (${lhs}..${rhs}) exceeds the maximum allowed span of ${MAX_FOR_RANGE_SPAN}`);
  }
}

/** Drains `node.children()`'s generator to its final `.value` — LiquidJS's `children()` seam
 * returns a generator even in the sync (`partials=false, sync=true`) mode this walker always
 * calls it in, so this is just the "give me the array" adapter over that shape. */
function drainChildren(node: WalkableNode): WalkableNode[] | undefined {
  if (typeof node.children !== "function") return undefined;
  const gen = node.children(false, true);
  let step = gen.next();
  while (!step.done) step = gen.next();
  return step.value;
}

/**
 * Recursively walk a parsed template's AST — using LiquidJS's public
 * `Template.children()` seam, the same mechanism the engine's own
 * `analyze()`/`analyzeSync()` static-analysis API uses internally — and
 * collect every tag name and filter name actually used, including inside
 * `if`/`unless`/`case`/`for` bodies and the `{% liquid %}` shorthand.
 * `children(false, true)` (partials=false, sync=true) never touches disk
 * even for filesystem tags like `include`/`render`/`layout` (verified in
 * `liquid-allowlist.test.ts`), so this is safe to run before those tags
 * have even been rejected by the allowlist below. Also flags an oversized
 * literal `for` range into `rangeViolations` (see `MAX_FOR_RANGE_SPAN`).
 *
 * @complexity O(n) in AST node count — one pass, no backtracking, no
 * re-visiting of a node.
 */
function collectLiquidUsage(
  nodes: WalkableNode[],
  tags: Set<string>,
  filters: Set<string>,
  rangeViolations: string[]
): void {
  for (const node of nodes) {
    collectNodeTag(node, tags);
    collectNodeValueFilters(node, filters);
    collectNodeArgumentFilters(node, filters);
    collectForRangeViolation(node, rangeViolations);
    const children = drainChildren(node);
    if (children) collectLiquidUsage(children, tags, filters, rangeViolations);
  }
}

/**
 * Lint a `.liquid` template source against the ADR-020 §3 tag/filter
 * allowlist.
 *
 * @param source raw `.liquid` template text (untrusted — third-party theme
 *   content).
 * @returns human-readable violation messages; empty means the template is
 *   clean. A Liquid syntax error is reported the same way (as a single
 *   violation message) rather than thrown, so every caller can treat this
 *   function as a total, non-throwing predicate.
 * @complexity O(n) in template size — one parse plus one AST walk.
 * @overallScore 100/100
 */
export function lintLiquidTemplate(source: string): string[] {
  let parsed: WalkableNode[];
  try {
    parsed = parser.parse(source) as unknown as WalkableNode[];
  } catch (err) {
    return [`Liquid syntax error: ${(err as Error).message}`];
  }

  const tags = new Set<string>();
  const filters = new Set<string>();
  const violations: string[] = [];
  collectLiquidUsage(parsed, tags, filters, violations);

  for (const tag of tags) {
    if (!ALLOWED_LIQUID_TAGS.has(tag)) violations.push(`disallowed tag "${tag}"`);
  }
  for (const filter of filters) {
    if (!ALLOWED_LIQUID_FILTERS.has(filter)) violations.push(`disallowed filter "${filter}"`);
  }
  return violations;
}

