import { requestThemePreviewRefresh } from "./preview-refresh.js";
import type { DiscoveredTheme } from "./theme.js";
import { syncThemeRoster } from "./theme-roster-sync.js";
import { verifyActiveThemeResolves } from "./verify-active-theme.js";

/**
 * @file `theme_set_active` (F7a, 2026-09-24) — the agent-callable half of "which theme does the
 * live site use", wired directly onto Jini's `setActiveTheme`/`resolveActiveThemeId` the same way
 * `server/inbound/admin-http/routes/presentation/patch-active-theme.ts`'s human route already is.
 *
 * Deliberately its OWN file, not an entry in `features/theme/agent-tools.ts` /
 * `tool-registrations.ts` (that domain's file-level catalog): this tool shares no validator with
 * `theme_read_file`/`theme_write_file` and the rest — it never touches a theme's files at all, only
 * `presentation_settings.active_theme_id` — so folding it into that 1000+-line file would mix two
 * unrelated write surfaces for no shared code. See `agent-tools.ts`'s own header, "Nothing here
 * touches the ACTIVE theme selection", for the boundary this keeps.
 *
 * Reversible (switching back is calling this again with the id this call returns as
 * `previousThemeId`), which under the owner's standing rule once meant no confirm — the posture
 * `patch-active-theme.ts`'s own PATCH route still has for a human. Superseded for the AGENT by the
 * owner decision of 2026-11-02: a demo chat switched the live site to a theme it had just rebuilt
 * without asking, so the tool's approval metadata (`contracts/core/tool-metadata/theme.ts`) is now
 * `publish`/`policy` and the shared approval wrapper shows the confirmation card first.
 *
 * `writableThemeIds` (moved to `features/theme/active-theme.ts` this same slice) is the ONE
 * allowlist this tool and the admin PATCH route both validate against — see that function's own doc
 * for why a second, private copy would have been the real risk here.
 */

/** The narrow slice this tool needs off the full assistant deps bag. */
export interface SetActiveThemeToolDeps {
  tracker?: Tracker;
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  /** Boot-discovered themes — the same mutable array `ThemeToolDeps.themes` reads, only ever read
   *  here (never mutated) to compute {@link writableThemeIds}. */
  themes: DiscoveredTheme[];
  presentationRepo: PresentationSettingsRepoPort;
  /** Production site directory; optional for contributors used without an open preview host. */
  themesDir?: string;
}

const SET_ACTIVE_THEME_CATALOG: AgentToolDefinition = {
  name: "theme_set_active",
  description:
    "Switches which theme the live site uses. Pass 'none' to turn the theme off. The person confirms the switch on a card first. Returns the " +
    "previous theme id, so the switch can be undone by calling this again with it. " +
    "Send only 'themeId' with the discovered theme id; do not also send id or activeThemeId. " +
    "Legacy id and activeThemeId spellings are aliases, not additional settings; differing values are refused.",
  sideEffects: "mutates-durable-state",
  authorization: { permission: "theme.set" },
  inputSchema: {
    type: "object",
    additionalProperties: false,
    required: ["themeId"],
    properties: {
      themeId: {
        type: "string",
        aliases: ["id", "activeThemeId"],
        minLength: 1,
        description: "A discovered theme's id to activate, or 'none' to turn the theme off.",
      },
    },
  },
};

/** This domain's full catalog — read by `tool-registrations.contracts.test.ts`'s `CATALOGS_BY_DOMAIN`. */
export const setActiveThemeAgentToolCatalog: AgentToolDefinition[] = [SET_ACTIVE_THEME_CATALOG];

const CATALOG_BY_ID = indexCatalogById({ catalog: setActiveThemeAgentToolCatalog });

/** This wiring layer's own risk classification — `setActiveTheme` writes
 *  `presentation_settings.active_theme_id`, a real, disk-affecting durable-state mutation. */
export const setActiveThemeDerivedRisk: DerivedRiskByToolId = new Map([["theme_set_active", "mutates-durable-state"]]);

/** Keep readiness and validation refusals actionable at the tool boundary; other failures propagate. */
function activationInputError(required: { error: unknown; routeDeps: SetActiveThemeToolDeps }): unknown {
  const { error, routeDeps } = required;
  if (error instanceof ThemeStylingRequiredError) return new ToolInputError({ message: error.message });
  // Re-thrown as a `ToolInputError` (a DIFFERENT themeId would fix this) with the valid ids
  // appended to the SAME message `setActiveTheme` raised — see this file's own header.
  if (error instanceof PresentationSettingsValidationError) {
    return new ToolInputError({ message: `${error.message} (valid ids: ${writableThemeIds(routeDeps).join(", ")})` });
  }
  return error;
}

/**
 * Switch the active theme and report the previous one — `theme_set_active`'s body after its
 * permission check, exported so `theme_duplicate`'s `activate: true` (`duplicate-theme-tool.ts`)
 * switches through the exact same validation, preview refresh, and error shape instead of a copy.
 * Callers check `theme.set` first; this function performs no authorization.
 *
 * With `themesDir` (the real site), the roster is synced with the folder first — a theme another
 * process created since boot is activatable — and the switch is verified afterwards
 * (`verifyActiveThemeResolves`): success is reported only when the public render will resolve the
 * theme itself rather than fall back.
 * @throws {ToolInputError} When `themeId` is not a writable theme id (valid ids appended), or when
 *   the saved id would not resolve on the public render (the previous theme is restored first).
 * @complexity O(t) in the discovered theme count (the writable-id allowlist), plus one settings write
 *   and up to two roster syncs.
 */
export async function applyActiveTheme(
  required: { routeDeps: SetActiveThemeToolDeps; themeId: string; actorId?: string },
  _optional: Record<string, never> = {}
): Promise<{ previousThemeId: string; activeThemeId: string }> {
  const { routeDeps, themeId } = required;
  if (routeDeps.themesDir) syncThemeRoster({ themes: routeDeps.themes, themesDir: routeDeps.themesDir });
  const previousThemeId = await resolveActiveThemeId(routeDeps);

  let activeThemeId: string;
  try {
    const result = await setActiveTheme({
      deps: {
        repo: routeDeps.presentationRepo,
        tracker: routeDeps.tracker,
        clock: routeDeps.clock,
        availableThemeIds: writableThemeIds(routeDeps, { requestedThemeId: themeId }),
      },
      input: { workspaceId: routeDeps.workspaceId, activeThemeId: themeId },
    }, { actorId: required.actorId, source: "assistant", capture: false });
    activeThemeId = result.settings.activeThemeId;
  } catch (err) {
    throw activationInputError({ error: err, routeDeps });
  }
  if (routeDeps.themesDir) {
    requestThemePreviewRefresh({ themesDir: routeDeps.themesDir });
    await verifyActiveThemeResolves({ deps: { ...routeDeps, themesDir: routeDeps.themesDir }, activeThemeId, previousThemeId });
  }
  if (previousThemeId !== activeThemeId) {
    try { routeDeps.tracker?.capture({ name: "theme_changed", userId: required.actorId ?? `system:${routeDeps.workspaceId}` }, { properties: { themeId: activeThemeId, source: "assistant" } }); }
    catch { /* Capture follows verification and cannot fail the active-theme operation. */ }
  }
  return { previousThemeId, activeThemeId };
}

function buildSetActiveThemeHandlers(routeDeps: SetActiveThemeToolDeps): Record<string, ToolHandler> {
  return {
    theme_set_active: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const themeId = requireString({ input: input, key: "themeId" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "theme.set" }, { entityType: "presentation" });

      return applyActiveTheme({ routeDeps, themeId, actorId: ctx.principal.id });
    },
  };
}

export function buildSetActiveThemeRegistrations(routeDeps: SetActiveThemeToolDeps): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "theme-set-active",
    catalogModule: "features/theme/set-active-theme-tool.ts",
    catalog: CATALOG_BY_ID,
    handlers: buildSetActiveThemeHandlers(routeDeps),
    derivedRisk: setActiveThemeDerivedRisk,
  });
}

/**
 * Contributes `theme_set_active` to the assistant's catalog — called once by
 * `server/runtime/composition/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`.
 * Domain key `"theme-set-active"`, deliberately distinct from `"theme"`
 * (`contributeThemesTools()`) — the tool-contribution registry replaces a domain's ENTIRE
 * contribution on re-registration by that key, so sharing the theme domain's own key here would
 * make one of the two contributors silently vanish rather than adding a fifth tool alongside it.
 */
export function contributeSetActiveThemeTools(): ToolContributor<SetActiveThemeToolDeps, unknown> {
  return {
    domain: "theme-set-active",
    build: buildSetActiveThemeRegistrations,
    risk: setActiveThemeDerivedRisk,
  };
}

import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import ts from "typescript";

/**
 * @file Enforces, as a repo-scanning static check, that no production call to
 * `SecretSealerPort.seal()` under `apps/website/src` omits `aad`.
 *
 * ## The gap this closes
 * `ports.ts`'s own header documents `aad` as optional at the PORT level, on purpose: the sealer is
 * a general-purpose AEAD primitive (see `secret-sealer.aesgcm.test.ts`'s "backward compatibility: a
 * value sealed with no aad still opens with no aad" case), and a hypothetical table with no natural
 * row identity to bind is explicitly allowed to seal with none. That is the right call for the
 * PRIMITIVE. It is the wrong call for CREDENTIAL STORES specifically: every credential-shaped table
 * in this codebase has an obvious identity to bind (workspace + provider + credential id, at
 * minimum), and the 2026-09-02 audit found `external_mcp_servers` had shipped sealing OAuth tokens
 * with no `aad` for exactly that reason — nothing enforced that every store actually uses the
 * binding the primitive makes available. This file is that enforcement, layered ON TOP of the
 * deliberately-permissive primitive rather than changing it: `SecretSealerPort.seal()`'s `aad`
 * parameter stays optional (removing the `?` would also invalidate the sealer's own documented
 * backward-compatibility contract and its regression test), and this check instead makes "every
 * ACTUAL call site in this codebase happens to always pass aad" an enforced fact instead of an
 * unenforced accident.
 *
 * ## Why an AST scan, not a type-level port change
 * See above — the port's optionality is a deliberate, tested, documented design choice for the
 * primitive, not an oversight. Narrowing it to `aad: string` would contradict that design and break
 * `secret-sealer.aesgcm.test.ts`'s own backward-compatibility test. The invariant this codebase
 * actually wants ("every CREDENTIAL STORE call site passes aad") is a policy about call sites, not
 * about the primitive's shape, so it belongs in a call-site check, not the type.
 *
 * ## Why an AST scan, not a one-line grep
 * A single-line regex on `.seal(` misses any call whose arguments span multiple lines —
 * `connector-credential-store.ts`'s `sealCredentials` helper is exactly this shape, and is the
 * concrete case that produced a wrong AAD count earlier in this effort. This walks the real
 * `ts.SourceFile` AST (same technique `ts-escape-metrics.mjs` already uses in this repo for
 * AST-accurate `any`/non-null-assertion counts) so call-site shape and formatting can never hide an
 * argument from it.
 *
 * ## Scope and precision trade-off
 * This matches every `CallExpression` whose callee is a property access named exactly `seal`,
 * anywhere under `apps/website/src` (excluding test files) — NOT resolved through the type checker
 * against `SecretSealerPort` specifically. That is a deliberate simplicity/robustness trade-off, not
 * an oversight: a full `ts.Program` + checker resolution would be strictly more precise (it could
 * tell a `SecretSealerPort.seal()` call apart from an unrelated future `.seal()` method on some
 * other type), but building a type-checked program over this monorepo's `@jini-ai/*` packages is
 * slower and more failure-prone than this check needs to be. Two unrelated methods now exist:
 * `PluginSourcePort.seal()` and `createPluginContributionCapture()`'s `seal()`. The exclusions below
 * pin each to its exact repo-relative file, receiver, method AND complete call text (apart from
 * whitespace). They do not exempt either file or receiver generally: a credential seal added in
 * either file, even on the same receiver name, still has its arguments checked. Unrecognized calls
 * remain fail-closed; a changed non-secret call needs review rather than a broader exemption.
 *
 * ## What counts as a violation
 * A matched call whose single argument is an object literal with:
 *   - no `aad` property at all (`reason: "missing-aad"`), or
 *   - an `aad` property whose value is the literal identifier `undefined`
 *     (`reason: "aad-literally-undefined"`).
 * A matched call whose argument is NOT a single plain object literal — built via a spread, passed
 * as a pre-built variable, or anything else this scan can't statically see into — is fail-closed
 * reported as `"unresolved-argument-shape"` rather than silently treated as compliant. Every one of
 * the 11 credential `.seal()` call sites checked when this was written passed a literal object
 * inline, so this fail-closed branch had zero real hits then; a future call site would have to
 * actively choose a shape this scan can't see through, and gets flagged rather than waved past
 * by default.
 *
 * `open()` is deliberately NOT covered here: its `aad` stays conditional on each row's own
 * `aadVersion`/`oauthAadVersion` field so legacy pre-migration rows (sealed before this codebase
 * required aad) can still be decrypted — see each store's own `sealCredentials`/`openCredentials`
 * pair. Enforcing "always pass aad" on `open()` would break that legitimate backward-compatibility
 * path, not catch a bug.
 *
 * Usage: npx tsx apps/website/src/features/webhooks/seal-aad-invariant.ts
 * Not part of the server build: the root `tsconfig.json` excludes this file, because it imports
 * `typescript` (a devDependency) and dist/ ships whole in the desktop payload. `typecheck:tests`
 * still type-checks it.
 * Exit codes: 0 = every non-exempt `.seal()` call site under scope supplies `aad`.
 *             1 = at least one does not, or has a shape this scan can't verify.
 */

const REPO_ROOT = path.resolve(import.meta.dirname, "..", "..", "..", "..", "..");
const DEFAULT_SCAN_ROOT = path.join(REPO_ROOT, "apps", "website", "src");

// These Jini plugin lifecycle calls seal source versions/contributions, never credentials.
// Exact arguments also prevent a SecretSealerPort call on `port` or `capture` from being exempted.
const NON_SECRET_SEAL_CALLS: Readonly<Record<string, string>> = {
  "apps/website/src/features/plugin-runtime/source-tools.ts": "port.seal({ id: pluginId }, {})",
  "apps/website/src/server/runtime/composition/plugin-runtime.ts": "capture.seal({ sdk: scopedSdk })",
};

function isTestFile(file: string): boolean {
  return /__tests__|\.test\.|\.spec\./.test(file);
}

function collectTsFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name === "dist") continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...collectTsFiles(full));
    } else if (/\.tsx?$/.test(entry.name) && !isTestFile(full)) {
      out.push(full);
    } else {
      // Non-source entries are outside the seal invariant.
    }
  }
  return out;
}

export interface SealViolation {
  /** Repo-root-relative path (real-scan mode) or the caller-supplied display path (unit-test mode). */
  file: string;
  /** 1-based line number of the call expression's start. */
  line: number;
  /** The call expression's source text, whitespace-collapsed to one line for reporting. */
  text: string;
  reason: "missing-aad" | "aad-literally-undefined" | "unresolved-argument-shape";
}

/**
 * Core per-file scanner, unit-testable directly against synthetic source text (no filesystem, no
 * `ts.Program`). Finds every `<expr>.seal(...)` call and checks its argument shape.
 *
 * @complexity O(n) single AST walk, n = node count in the parsed file.
 */
export function findSealCallsInSource(sourceText: string, displayPath: string): SealViolation[] {
  const scriptKind = displayPath.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const source = ts.createSourceFile(displayPath, sourceText, ts.ScriptTarget.Latest, true, scriptKind);
  const violations: SealViolation[] = [];

  function lineOf(pos: number): number {
    return source.getLineAndCharacterOfPosition(pos).line + 1;
  }

  function visit(node: ts.Node): void {
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression) && node.expression.name.text === "seal") {
      const violation = checkSealCallArguments(node, source, displayPath, lineOf);
      if (violation) violations.push(violation);
    }
    ts.forEachChild(node, visit);
  }
  visit(source);

  return violations;
}

function buildSealViolation(
  reason: SealViolation["reason"],
  displayPath: string,
  line: number,
  text: string,
): SealViolation {
  return { file: displayPath, line, text, reason };
}

/** Finds the `aad` property among a `.seal()` call's object-literal properties. Returns
 *  `"unresolved"` when a spread makes it impossible to statically know whether `aad` is
 *  included (fail-closed — see file header), or `null` when no `aad` property is present. */
function findAadProperty(
  properties: ts.NodeArray<ts.ObjectLiteralElementLike>,
): ts.ObjectLiteralElementLike | "unresolved" | null {
  for (const prop of properties) {
    if (ts.isSpreadAssignment(prop)) return "unresolved";
    if (prop.name && ts.isIdentifier(prop.name) && prop.name.text === "aad") return prop;
  }
  return null;
}

function isLiterallyUndefined(prop: ts.ObjectLiteralElementLike): boolean {
  return (
    ts.isPropertyAssignment(prop) && ts.isIdentifier(prop.initializer) && prop.initializer.text === "undefined"
  );
}

function checkSealCallArguments(
  call: ts.CallExpression,
  source: ts.SourceFile,
  displayPath: string,
  lineOf: (pos: number) => number,
): SealViolation | null {
  const line = lineOf(call.getStart(source));
  const text = call.getText(source).replace(/\s+/g, " ").trim();

  if (NON_SECRET_SEAL_CALLS[displayPath] === text) return null;

  if (call.arguments.length !== 1 || !ts.isObjectLiteralExpression(call.arguments[0])) {
    return buildSealViolation("unresolved-argument-shape", displayPath, line, text);
  }

  const aadProp = findAadProperty(call.arguments[0].properties);
  if (aadProp === "unresolved") return buildSealViolation("unresolved-argument-shape", displayPath, line, text);
  if (aadProp === null) return buildSealViolation("missing-aad", displayPath, line, text);
  if (isLiterallyUndefined(aadProp)) return buildSealViolation("aad-literally-undefined", displayPath, line, text);

  return null; // `aad` present with a real value, or shorthand `{ aad }` — compliant.
}

/** Real-repo scan: every non-test `.ts`/`.tsx` file under `scanRoot`, reported paths relative to
 * the repo root. Defaults to `apps/website/src` — the only surface `SecretSealerPort.seal()` is
 * called from today. */
export function findSealCallsWithoutAad(scanRoot: string = DEFAULT_SCAN_ROOT): SealViolation[] {
  const violations: SealViolation[] = [];
  for (const file of collectTsFiles(scanRoot)) {
    const sourceText = fs.readFileSync(file, "utf8");
    violations.push(...findSealCallsInSource(sourceText, path.relative(REPO_ROOT, file)));
  }
  return violations;
}

function main(): void {
  const violations = findSealCallsWithoutAad();

  if (violations.length === 0) {
    console.log("check:seal-aad — OK: every SecretSealerPort.seal() call site under apps/website/src supplies aad.");
    return;
  }

  console.error(`check:seal-aad — ${violations.length} .seal() call site(s) do not verifiably supply aad:`);
  for (const v of violations) {
    console.error(`  - ${v.file}:${v.line} [${v.reason}] ${v.text}`);
  }
  console.error(`\nEvery credential store's seal() call must pass its own row-identity aad (see any of the\nexisting */aad.ts helpers for the pattern) — or, if this really is a call this scan can't see\nthrough safely, resolve it explicitly rather than leaving it unresolved.`);
  process.exit(1);
}

// Guarded, matching `check-theme-replaced-elements.ts`/`check-src-complexity-drift.ts`: this file's
// exported functions are imported directly by `__tests__/seal-aad-invariant.test.ts`, and an
// unguarded `main()` would scan the real repo (and `process.exit(1)` if it ever regresses) as a
// side effect of that import.
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
